// Writes src/python/words.rs: the words that the big alternations of the
// `python` grammar spell out, expanded and sorted, so a matcher can test a
// whole word against a list.
//
// Run with `bun run oracle/python-words.ts` and commit the result; the output
// is generated, do not edit it.
import python from "@shikijs/langs@4.6.0/python";
import { dedent } from "./dedent.ts";

type Node = { match?: string; begin?: string; patterns?: Node[] };
const repository = (python as unknown as { repository: Record<string, Node> }[])[0]!.repository;

/** The regex of the `index`th pattern of repository entry `key`, or of the entry itself. */
function regexOf(key: string, index?: number): string {
  const entry = repository[key]!;
  const node = index === undefined ? entry : entry.patterns![index]!;
  return (node.match ?? node.begin)!;
}

/** Expands a regex of literals, groups, alternation and `?` into its words. */
function words(regex: string): string[] {
  let pos = 0;
  const alternation = (): string[] => {
    let result: string[] = [];
    let branch: string[] = [""];
    while (pos < regex.length && regex[pos] !== ")") {
      const c = regex[pos]!;
      if (c === "|") {
        pos++;
        result = result.concat(branch);
        branch = [""];
        continue;
      }
      let atom: string[];
      if (c === "(") {
        pos++;
        if (regex.startsWith("?:", pos)) pos += 2;
        atom = alternation();
        pos++;
      } else {
        atom = [c];
        pos++;
      }
      if (regex[pos] === "?") {
        pos++;
        if (regex[pos] === "?") pos++;
        atom = ["", ...atom];
      }
      branch = branch.flatMap((b) => atom.map((a) => b + a));
    }
    return result.concat(branch);
  };
  return alternation();
}

function wordList(name: string, regex: string, doc: string): string {
  const m = /^(?:\(\?<!\\\.\))?\\b\((?:\?:)?(.*)\)\\b$/.exec(regex);
  if (!m) throw new Error(regex);
  const list = [...new Set(words(m[1]!))].filter((w) => w.length > 0).sort();
  return dedent`
    /// ${doc}
    pub(super) const ${name}: &[&[u8]] = &[
    ${list.map((w) => `    b"${w}",`).join("\n")}
    ];
    `;
}

let out = dedent`
  //! The words the grammar's alternations spell out, sorted. Generated by
  //! \`oracle/python-words.ts\`; do not edit.

  `;
out += wordList("BUILTIN_FUNCTIONS", regexOf("builtin-functions", 0), "The words of `builtin-functions`.") + "\n";
out += wordList("LEGACY_BUILTINS", regexOf("builtin-functions", 1), "The legacy builtins.") + "\n";
out += wordList("BUILTIN_TYPES", regexOf("builtin-types"), "The words of `builtin-types`.") + "\n";
out += wordList("BUILTIN_EXCEPTIONS", regexOf("builtin-exceptions"), "The words of `builtin-exceptions`.") + "\n";
out += wordList("MAGIC_FUNCTIONS", regexOf("magic-function-names"), "The words of `magic-function-names`.") + "\n";
out += wordList("MAGIC_VARIABLES", regexOf("magic-variable-names"), "The words of `magic-variable-names`.");
await Bun.write(new URL("../src/python/words.rs", import.meta.url).pathname, out);
